// Arma un solo UPDATE para todo lo que se proceso en la corrida, haya salido
// bien o mal.
//
// Un unico statement maneja los dos casos con CASE:
//   - classification_attempts sube SIEMPRE, asi un aviso que falla sin parar
//     llega a 3 y deja de reintentarse en vez de girar para siempre
//   - las columnas de clasificacion solo se escriben cuando ok = true
//   - classified_at solo se marca cuando ok = true, asi lo que fallo vuelve a
//     entrar en la proxima corrida

const rows = $input.all().map(i => {
  const o  = i.json;
  const ok = o.ok === true;

  return {
    db_id: o.db_id,
    ok,
    error: ok ? null : String(o.error || 'error desconocido').slice(0, 500),
    job_function:     ok ? o.job_function : null,
    level:            ok ? o.level : null,
    tags:             ok ? (o.tags || []) : [],
    suggested_tags:   ok ? (o.suggested_tags || []) : [],
    work_mode:        ok ? o.work_mode : null,
    countries:        ok ? (o.countries || []) : [],
    regions:          ok ? (o.regions || []) : [],
    eligible:         ok ? o.eligible : null,
    is_agency:        ok ? o.is_agency : null,
    is_evergreen:     ok ? o.is_evergreen : null,
    note:             ok ? o.note : null,
    taxonomy_version: ok ? o.taxonomy_version : null,
  };
});

// Sin nada que procesar, no se dispara ninguna query.
if (!rows.length) return [];

// Los arrays viajan como jsonb y se convierten a text[] del lado de Postgres:
// jsonb_to_recordset no convierte arrays JSON a text[] de forma confiable.
const sql = `
UPDATE jobs j SET
  classification_attempts = j.classification_attempts + 1,
  classification_error    = CASE WHEN v.ok THEN NULL ELSE v.error END,

  job_function        = CASE WHEN v.ok THEN v.job_function ELSE j.job_function END,
  level               = CASE WHEN v.ok THEN v.level        ELSE j.level END,
  tags                = CASE WHEN v.ok THEN ARRAY(SELECT jsonb_array_elements_text(v.tags))
                                       ELSE j.tags END,
  suggested_tags      = CASE WHEN v.ok THEN ARRAY(SELECT jsonb_array_elements_text(v.suggested_tags))
                                       ELSE j.suggested_tags END,
  work_mode           = CASE WHEN v.ok THEN v.work_mode    ELSE j.work_mode END,
  countries           = CASE WHEN v.ok THEN ARRAY(SELECT jsonb_array_elements_text(v.countries))
                                       ELSE j.countries END,
  regions             = CASE WHEN v.ok THEN ARRAY(SELECT jsonb_array_elements_text(v.regions))
                                       ELSE j.regions END,
  eligible            = CASE WHEN v.ok THEN v.eligible     ELSE j.eligible END,
  is_agency           = CASE WHEN v.ok THEN v.is_agency    ELSE j.is_agency END,
  is_evergreen        = CASE WHEN v.ok THEN v.is_evergreen ELSE j.is_evergreen END,
  classification_note = CASE WHEN v.ok THEN v.note         ELSE j.classification_note END,
  classified_at       = CASE WHEN v.ok THEN now()          ELSE j.classified_at END,
  taxonomy_version    = CASE WHEN v.ok THEN v.taxonomy_version ELSE j.taxonomy_version END
FROM jsonb_to_recordset($1::jsonb) AS v(
  db_id            int,
  ok               boolean,
  error            text,
  job_function     text,
  level            text,
  tags             jsonb,
  suggested_tags   jsonb,
  work_mode        text,
  countries        jsonb,
  regions          jsonb,
  eligible         boolean,
  is_agency        boolean,
  is_evergreen     boolean,
  note             text,
  taxonomy_version smallint
)
WHERE j.id = v.db_id;
`;

const params = JSON.stringify(rows);
const ok     = rows.filter(r => r.ok).length;

console.log('=== UPDATE SQL ===');
console.log('filas: ' + rows.length + '  ·  clasificadas: ' + ok + '  ·  fallidas: ' + (rows.length - ok));

return [{ json: { sql, params, rows: rows.length } }];

// Toma la respuesta de Gemini, la valida contra las listas cerradas y la deja
// lista para el UPDATE.
//
// Devuelve TODOS los avisos que proceso, no solo los que salieron bien:
//   ok: true   -> se clasifico, el UPDATE escribe las columnas
//   ok: false  -> fallo, el UPDATE solo suma el intento y guarda el motivo
//
// Que los fallos tambien salgan por aca es lo que permite contarlos. Si se
// descartaran en silencio, un aviso que falla siempre se reintentaria para
// siempre y nadie se enteraria.

const FUNCIONES  = ['engineering','product','design','marketing','sales','operations','support','other'];
const NIVELES    = ['junior','mid','senior','staff','lead','manager','director','vp'];
const TAGS       = ['backend','frontend','fullstack','mobile','infra','data','ml','ai','security','qa','sap','salesforce'];
const WORK_MODES = ['remote','hybrid','onsite'];
const REGIONES   = ['latam','namerica','emea','apac','global'];

// Paises de LATAM y Norteamerica en ISO de dos letras. Sirven para una sola
// cosa: garantizar que si el modelo puso un pais, la region correspondiente
// tambien este. Si no, un aviso en ['BR'] sin 'latam' en regions se perderia
// del filtro "abierto a LATAM" de la app.
const ISO_LATAM = new Set([
  'AR','BO','BR','CL','CO','CR','CU','DO','EC','SV','GT','HN','MX','NI','PA',
  'PY','PE','PR','UY','VE','JM','TT','BS','BB','HT','BZ','GY','SR',
]);
const ISO_NAMERICA = new Set(['US','CA']);

// Encuentra el primer objeto JSON *balanceado* dentro de un texto y lo parsea.
//
// Esto no es un parche para un caso puntual: el modelo a veces envuelve la
// respuesta con basura — una llave de mas al principio ( {{...}] ), un corchete
// al final, comillas de markdown, o texto suelto antes del JSON. En vez de
// adivinar la forma del envoltorio, lo ignoramos entero y buscamos adentro.
function extraerObjeto(txt) {
  const s = String(txt || '');

  for (let start = s.indexOf('{'); start !== -1; start = s.indexOf('{', start + 1)) {
    let depth = 0, inStr = false, esc = false;

    for (let i = start; i < s.length; i++) {
      const ch = s[i];

      // Las llaves adentro de un string no cuentan:  "note": "usa {esto}"
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (ch === '"')  { inStr = !inStr; continue; }
      if (inStr) continue;

      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) {
          try {
            const o = JSON.parse(s.slice(start, i + 1));
            if (o && o.job_function) return o;
          } catch (e) { /* no era: probamos desde el proximo '{' */ }
          break;
        }
      }
    }
  }
  return null;
}

// Cada version del nodo de Gemini envuelve la respuesta distinto, asi que en
// vez de adivinar la ruta, buscamos en profundidad el primer objeto que tenga
// job_function — venga como objeto o como texto adentro de algun campo.
function buscar(v, depth = 0) {
  if (v == null || depth > 8) return null;

  if (typeof v === 'string') return extraerObjeto(v);

  if (typeof v === 'object') {
    if (v.job_function) return v;
    for (const k of Object.keys(v)) {
      const r = buscar(v[k], depth + 1);
      if (r) return r;
    }
  }
  return null;
}

const lista = v => (Array.isArray(v) ? v : []);

const respuestas = $input.all();
const entradas   = $('Build prompts').all();

const out = [];
const problemas = [];
let sinNivel = 0;
let sinModo = 0;
let fallos = 0;

respuestas.forEach((r, i) => {
  const entrada = entradas[i]?.json || {};

  // Sin db_id no hay fila que actualizar: no tiene sentido ni contar el intento.
  if (!entrada.db_id) return;

  const c = buscar(r.json);

  if (!c) {
    fallos++;
    problemas.push(`[${i}] ${entrada.title || '?'} -> respuesta no parseable`);
    if (fallos === 1) {
      console.log('=== RAW DEL PRIMER FALLO ===');
      console.log(JSON.stringify(r.json).slice(0, 1500));
    }
    out.push({ json: {
      ok: false,
      db_id: entrada.db_id,
      title: entrada.title,
      error: 'respuesta no parseable',
    }});
    return;
  }

  // job_function es obligatoria. Si viene fuera de lista no inventamos un
  // valor: lo tratamos como fallo, se reintenta, y queda el motivo escrito.
  if (!FUNCIONES.includes(c.job_function)) {
    fallos++;
    const err = `job_function fuera de lista: "${c.job_function}"`;
    problemas.push(`[${i}] ${entrada.title || '?'} -> ${err}`);
    out.push({ json: {
      ok: false,
      db_id: entrada.db_id,
      title: entrada.title,
      error: err,
    }});
    return;
  }

  // "unknown" es una respuesta legitima: se guarda como NULL, no como texto.
  // Asi el frontend puede tratarlo como "mostralo igual" en vez de excluirlo.
  const level = NIVELES.includes(c.level) ? c.level : null;
  if (level === null) sinNivel++;

  const tags      = lista(c.tags).filter(t => TAGS.includes(t));
  const tagsFuera = lista(c.tags).filter(t => !TAGS.includes(t));

  // Texto libre: se normaliza pero no se valida contra ninguna lista.
  // Nunca llega a los filtros; solo alimenta la revision periodica.
  //
  // Los tags que el modelo invento entran aca tambien: un tag fuera de lista
  // y un suggested_tag dicen lo mismo — "vi algo que tu taxonomia no cubre".
  const sugeridos = [...new Set(
    [...lista(c.suggested_tags), ...tagsFuera]
      .map(t => String(t || '').toLowerCase().trim())
      .filter(t => t && t.length <= 40 && !TAGS.includes(t))
  )].slice(0, 3);

  // --- Geografia ---------------------------------------------------------

  // "unknown" o cualquier cosa fuera de lista se guarda como NULL, igual que
  // el nivel: es honesto y el frontend lo puede mostrar como "no especifica".
  const modo = String(c.work_mode || '').toLowerCase().trim();
  const work_mode = WORK_MODES.includes(modo) ? modo : null;
  if (work_mode === null) sinModo++;

  // ISO de dos letras en mayuscula, sin repetidos. Lo que no tenga esa forma
  // ("Argentina", "USA") se descarta: el filtro de la app compara codigos.
  const countries = [...new Set(
    lista(c.countries)
      .map(p => String(p || '').toUpperCase().trim())
      .filter(p => /^[A-Z]{2}$/.test(p))
  )].slice(0, 15);

  const regions = new Set(
    lista(c.regions)
      .map(r => String(r || '').toLowerCase().trim())
      .filter(r => REGIONES.includes(r))
  );

  // Consistencia: si hay un pais, su region tiene que estar.
  if (countries.some(p => ISO_LATAM.has(p)))    regions.add('latam');
  if (countries.some(p => ISO_NAMERICA.has(p))) regions.add('namerica');

  // -----------------------------------------------------------------------

  out.push({ json: {
    ok: true,
    db_id: entrada.db_id,
    external_id: entrada.external_id,
    title: entrada.title,
    job_function: c.job_function,
    level,
    tags,
    suggested_tags: sugeridos,
    work_mode,
    countries,
    regions: [...regions],
    eligible: c.eligible === true,
    is_agency: c.is_agency === true,
    is_evergreen: c.is_evergreen === true,
    note: String(c.note || '').slice(0, 300),
    taxonomy_version: entrada.taxonomy_version ?? 2,
    error: null,
  }});
});

const ok = out.length - fallos;

console.log('=== PARSE ===');
console.log('respuestas: ' + respuestas.length +
            '  ·  clasificadas: ' + ok +
            '  ·  fallos: ' + fallos +
            '  ·  sin nivel: ' + sinNivel +
            '  ·  sin modo: ' + sinModo);
console.log(problemas.length ? 'PROBLEMAS:\n  ' + problemas.join('\n  ') : 'sin problemas');
console.log('---');
for (const { json: o } of out) {
  if (!o.ok) {
    console.log(`FALLO  ${o.title}`);
    console.log(`       ↳ ${o.error}`);
    continue;
  }
  console.log(
    `${o.job_function.padEnd(12)} ${(o.level || 'unknown').padEnd(9)} ` +
    `${(o.work_mode || '?').padEnd(7)} ` +
    `[${o.countries.join(',')}]`.padEnd(10) +
    `{${o.regions.join(',')}}`.padEnd(18) +
    ` elig=${o.eligible ? 'si' : 'NO'}  ${o.title}`
  );
  console.log(`       ↳ ${o.note}` +
    (o.suggested_tags.length ? `   ⟨sugeridos: ${o.suggested_tags.join(', ')}⟩` : ''));
}

return out;
